# application.yml (defaults)
payment:
  url: https://sandbox.gateway.com
  timeout: 5s

# application-prod.yml (another file; only what changes)
payment:
  url: https://api.gateway.com

# Activate: SPRING_PROFILES_ACTIVE=prod

@Validated
@ConfigurationProperties(prefix = "payment")
public record PaymentProperties(@NotBlank String url, @NotNull Duration timeout) {}

@SpringBootApplication
@EnableConfigurationProperties(PaymentProperties.class)
public class Application {}

@Service   // singleton: one instance shared by all requests
public class CatalogService {
    private final ProductRepository products;

    public CatalogService(ProductRepository products) {
        this.products = products;
    }

    @PostConstruct
    void warmUpCache() {
        // runs once, after injection
    }
}

@Component
@Scope("prototype")
public class ReportGenerator { }   // a new instance for each injection

// WRONG: one list for all users
@Service
public class CartService {
    private final List<Item> items = new ArrayList<>();
    public void add(Item item) { items.add(item); }
}

// RIGHT: state in the database, identified by a parameter
@Service
public class CartService {
    private final CartRepository carts;
    public CartService(CartRepository carts) { this.carts = carts; }

    @Transactional
    public void add(Long cartId, Item item) {
        carts.findById(cartId).orElseThrow().add(item);
    }
}

@Service
public class TransferService {

    @Transactional(isolation = Isolation.READ_COMMITTED, rollbackFor = InsufficientFundsException.class)
    public void transfer(Long from, Long to, BigDecimal amount) throws InsufficientFundsException {
        accounts.debit(from, amount);
        accounts.credit(to, amount);
    }

    @Transactional(readOnly = true)
    public Statement statement(Long accountId) { /* ... */ }
}

@Service
class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void record(String event) { /* saved even if the caller's transaction fails */ }
}

// WRONG: one bad row poisons the shared transaction
@Transactional
public void importAll(List<Row> rows) {
    for (Row r : rows) {
        try { rowService.importRow(r); }      // @Transactional (REQUIRED) in another bean
        catch (RuntimeException e) { log.warn("Skipping row", e); }
    }
}
// UnexpectedRollbackException: Transaction silently rolled back because it has been marked as rollback-only

// RIGHT: each row in its own transaction (and importAll not @Transactional)
@Transactional(propagation = Propagation.REQUIRES_NEW)
public void importRow(Row r) { ... }

@Service
public class OrderService {
    public void processBatch(List<Order> orders) {
        orders.forEach(this::save);          // self-invocation: does NOT go through the proxy
    }

    @Transactional
    public void save(Order o) { /* ... */ }
}

// RIGHT: the transactional method in another bean
@Service
public class BatchService {
    private final OrderService orderService;
    public BatchService(OrderService orderService) { this.orderService = orderService; }

    public void processBatch(List<Order> orders) {
        orders.forEach(orderService::save);  // goes through the proxy
    }
}

// WRONG: ignored
@Transactional
private void saveAll(List<Order> orders) { ... }

// RIGHT
@Transactional
public void saveAll(List<Order> orders) { ... }   // called from another bean

public interface OrderRepository extends JpaRepository<Order, Long> {

    @Query("select o from Order o join fetch o.items where o.customer.id = :customerId")
    List<Order> withItems(@Param("customerId") Long customerId);

    @EntityGraph(attributePaths = {"items", "customer"})
    Optional<Order> findDetailedById(Long id);
}

# application.yml (dev/test only)
spring.jpa.properties.hibernate.generate_statistics: true

// WRONG
@Query("select o from Order o join fetch o.items")
Page<Order> findAllWithItems(Pageable page);
// WARN HHH90003004: firstResult/maxResults specified with collection fetch; applying in memory

// RIGHT: 1) page the ids  2) fetch those orders with their items
@Query("select o.id from Order o")
Page<Long> findIds(Pageable page);

@Query("select o from Order o join fetch o.items where o.id in :ids")
List<Order> findWithItems(@Param("ids") List<Long> ids);
